            let val_ptr: *const u64 = &e.val;
            let h = crate::exe::call_va!(0x1424b16a0, (e.ptr, e.len) -> u64);
            let prod = (h as u128).wrapping_mul(0xde5f_b9d2_6304_58e9u128);
